      out.x = (v.x - mean) * rstd * g.x + b.x;
      out.y = (v.y - mean) * rstd * g.y + b.y;
      out.z = (v.z - mean) * rstd * g.z + b.z;
      out.w = (v.w - mean) * rstd * g.w + b.w;
      y4[i] = out;
    }
  } else {
    const int64_t per = (M + blocks_per_row - 1) / blocks_per_row;
    const int64_t start = chunk * per;
    const int64_t end = min(M, start + per);
    for (int64_t i = start + threadIdx.x; i < end; i += blockDim.x) {
      float v = x_row[i];
      y_row[i] = (v - mean) * rstd * G[i] + Bb[i];
    }
